import{_ as i,C as s,o as t,c as n,a2 as a,b as l,w as o,a as d,E as c,a3 as g}from"./chunks/framework.Brv5O9VI.js";const k=JSON.parse('{"title":"14.14 Observability, Monitoring & Operations","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.14-observability-and-operations.md","filePath":"system-design/14.14-observability-and-operations.md"}'),u={name:"system-design/14.14-observability-and-operations.md"};function h(p,e,m,b,f,y){const r=s("Mermaid");return t(),n("div",null,[e[1]||(e[1]=a('<h1 id="_14-14-observability-monitoring-operations" tabindex="-1">14.14 Observability, Monitoring &amp; Operations <a class="header-anchor" href="#_14-14-observability-monitoring-operations" aria-label="Permalink to &quot;14.14 Observability, Monitoring &amp; Operations&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Observability is the ability to understand a system&#39;s internal health, diagnose latency spikes, and trace runtime errors through the &quot;Three Pillars&quot;: Structured Logging, Quantitative Metrics, and Distributed Tracing.</p><hr><h2 id="_2-how-this-project-uses-it" tabindex="-1">2. How THIS Project Uses It <a class="header-anchor" href="#_2-how-this-project-uses-it" aria-label="Permalink to &quot;2. How THIS Project Uses It&quot;">​</a></h2><ul><li><strong>Logging</strong>: Standard Uvicorn ASGI stdout logs streaming unbuffered via <code>PYTHONUNBUFFERED=1</code> in [<code>Dockerfile:L3</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/Dockerfile#L3).</li><li><strong>Pre-Flight Health Monitoring</strong>: [<code>smoke_check.py:L1-L50</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/smoke_check.py#L1-L50) executes automated endpoint verification and latency assertions.</li><li><strong>Prometheus / OpenTelemetry / Sentry</strong>: <strong>Not Used in Code</strong>. For current single-container operation, standard stdout log streaming to container logs is adequate [CONFIRM WITH DEVELOPER].</li></ul>',6)),(t(),l(g,null,{default:o(()=>[c(r,{id:"mermaid-30",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20App%5B%22FastAPI%20Microservice%20(app.py)%22%5D%20--%3E%20Middle%5B%22Logging%20Middleware%22%5D%0A%20%20%20%20Middle%20--%3E%20JSONLog%5B%22Structured%20JSON%20Logs%20(Stdout)%22%5D%0A%20%20%20%20Middle%20--%3E%20Prom%5B%22Prometheus%20Counter%20%26%20Histogram%20Metrics%22%5D%0A%20%20%20%20Middle%20--%3E%20Trace%5B%22OpenTelemetry%20Traces%20(Trace%20ID)%22%5D%0A%20%20%20%20%0A%20%20%20%20JSONLog%20--%3E%20Fluentd%5B%22Fluentd%20%2F%20Vector%20Collector%22%5D%0A%20%20%20%20Fluentd%20--%3E%20Elastic%5B%22Elasticsearch%20%2F%20CloudWatch%22%5D%0A%20%20%20%20Prom%20--%3E%20Grafana%5B%22Grafana%20Dashboards%22%5D%0A%20%20%20%20Trace%20--%3E%20Jaeger%5B%22Jaeger%20Distributed%20Tracing%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_3-comparison-with-observability-tools" tabindex="-1">3. Comparison with Observability Tools <a class="header-anchor" href="#_3-comparison-with-observability-tools" aria-label="Permalink to &quot;3. Comparison with Observability Tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Observability Layer</th><th style="text-align:left;">Solution Used</th><th style="text-align:left;">Recommended Enterprise Stack</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Structured Logging</strong></td><td style="text-align:left;">Uvicorn stdout stream</td><td style="text-align:left;"><strong>Structlog / JSON logs</strong></td><td style="text-align:left;">Request tracing, client IP hashing, error root-cause</td></tr><tr><td style="text-align:left;"><strong>Metrics Collection</strong></td><td style="text-align:left;">Script assertions (<code>smoke_check.py</code>)</td><td style="text-align:left;"><strong>Prometheus + Grafana</strong></td><td style="text-align:left;">RPS, CPU utilization, p95/p99 latency percentiles</td></tr><tr><td style="text-align:left;"><strong>Distributed Tracing</strong></td><td style="text-align:left;">None</td><td style="text-align:left;"><strong>OpenTelemetry + Jaeger</strong></td><td style="text-align:left;">Hop-by-hop latency tracing</td></tr><tr><td style="text-align:left;"><strong>Error Tracking</strong></td><td style="text-align:left;">Console tracebacks</td><td style="text-align:left;"><strong>Sentry SDK</strong></td><td style="text-align:left;">Automated alert notifications for unhandled 500 exceptions</td></tr></tbody></table><hr><h2 id="_4-trade-offs-accepted" tabindex="-1">4. Trade-offs Accepted <a class="header-anchor" href="#_4-trade-offs-accepted" aria-label="Permalink to &quot;4. Trade-offs Accepted&quot;">​</a></h2><ul><li><strong>No Aggregated Latency Tracking</strong>: Without Prometheus histograms, monitoring p99 latency regressions requires manual log parsing or synthetic test runs via <code>smoke_check.py</code>.</li></ul><hr><h2 id="_5-what-breaks-at-scale" tabindex="-1">5. What Breaks at Scale <a class="header-anchor" href="#_5-what-breaks-at-scale" aria-label="Permalink to &quot;5. What Breaks at Scale&quot;">​</a></h2><ul><li><strong>At 10x Load</strong>: Docker stdout streams handle the load cleanly.</li><li><strong>At 100x Load</strong>: Unstructured text logs become difficult to query across multiple container instances during outages.</li><li><strong>At 1000x Load</strong>: Lack of correlation IDs makes debugging transient distributed timeouts across multiple pods impossible.</li></ul><hr><h2 id="_6-how-a-senior-engineer-would-improve-it" tabindex="-1">6. How a Senior Engineer Would Improve It <a class="header-anchor" href="#_6-how-a-senior-engineer-would-improve-it" aria-label="Permalink to &quot;6. How a Senior Engineer Would Improve It&quot;">​</a></h2><ol><li>Add <code>prometheus-fastapi-instrumentator</code> to expose a <code>/metrics</code> endpoint collecting: <ul><li><code>http_requests_total{status=&quot;200&quot;}</code></li><li><code>inference_latency_seconds_bucket</code></li></ul></li><li>Add correlation ID middleware injecting <code>X-Request-ID</code> into every response header and log line.</li></ol><hr><h2 id="_7-30-second-spoken-answer" tabindex="-1">7. 30-Second Spoken Answer <a class="header-anchor" href="#_7-30-second-spoken-answer" aria-label="Permalink to &quot;7. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;We currently log structured events to stdout with unbuffered Python streaming, which container logging drivers like Fluentd forward cleanly. For enterprise staging, we would integrate Prometheus metrics middleware and correlation IDs to track p95 and p99 inference latency on Grafana dashboards and alert on unexpected error rate spikes.&quot;</p></blockquote>',15))])}const x=i(u,[["render",h]]);export{k as __pageData,x as default};
